<script setup>
import {formatUnixTime} from '../shared/datePresentation.js'

import PageHeader from '../shared/components/PageHeader.vue'
import PageSurface from '../shared/components/PageSurface.vue'
import WorkflowSkills from './WorkflowSkills.vue'
import CreatedTokenSecret from './CreatedTokenSecret.vue'
import {useTableLayout} from '../shared/composables/tableLayout.js'
const {pinTableActions}=useTableLayout()
import {ref,computed,onMounted,watch} from 'vue'

import {toast} from '../shared/composables/toast.js'
import {copyText} from '../shared/clipboard.js'
const tab=ref('tokens'),tokens=ref([]),tools=ref([]),audit=ref([]),loading=ref(false),creating=ref(false),dialog=ref(false),error=ref(''),secret=ref(''),formRef=ref(),environments=ref([]),applications=ref([])
watch([dialog,creating],()=>{if(window.parent!==window)window.parent.postMessage({type:'workspace.dirty',dirty:dialog.value,busy:creating.value},location.origin)},{immediate:true})
const grantableScopes=ref([]),loadingScopes=ref(false)
const editing=ref(null)
const form=ref({name:'',expires_in_days:30,scopes:[],applications:[],environments:[]})
const selectableScopes=computed(()=>[...new Set([...grantableScopes.value,...(editing.value?.scopes||[])])].sort())
const scopeGroups=computed(()=>[
 {label:'查询',scopes:selectableScopes.value.filter(scope=>scope.endsWith(':read'))},
 {label:'维护与准备',scopes:selectableScopes.value.filter(scope=>scope.endsWith(':write')||scope.endsWith(':prepare'))},
 {label:'执行',scopes:selectableScopes.value.filter(scope=>scope.endsWith(':execute')||scope.endsWith(':trigger'))},
].filter(group=>group.scopes.length))
const scopesSelected=computed(()=>selectableScopes.value.length>0&&selectableScopes.value.every(scope=>form.value.scopes.includes(scope)))
const toggleScopes=()=>{form.value.scopes=scopesSelected.value?[]:[...selectableScopes.value]}
const config=['[mcp_servers.devOps]','url = "'+location.origin+'/api/plugins/devtools/mcp"','bearer_token_env_var = "LOGPLATFORM_MCP_TOKEN"','enabled = true','default_tools_approval_mode = "writes"','tool_timeout_sec = 120'].join('\n')
const fmt=formatUnixTime
const state=t=>t.revoked?'已撤销':t.expires_at<Date.now()/1000?'已过期':'有效'
async function api(path,options){const response=await fetch('api/'+path,options),body=await response.json();if(!response.ok)throw Error(body.error||'请求失败');return body}
async function load(){loading.value=true;try{const rows=await api(tab.value==='audit'?'audit?limit=100':tab.value==='tools'?'tools':'tokens');if(!Array.isArray(rows))throw Error('服务响应格式无效');(tab.value==='audit'?audit:tab.value==='tools'?tools:tokens).value=rows}catch(e){toast(e.message,'error')}finally{loading.value=false}}
watch(tab,value=>{if(value!=='setup')load()})
async function loadScopes(){
 if(loadingScopes.value)return false
 loadingScopes.value=true
 try{
  const scopes=await api('tokens/scopes')
  if(!Array.isArray(scopes))throw Error('令牌权限列表格式无效')
  grantableScopes.value=scopes
  return true
 }catch(e){toast(e.message,'error');return false}
 finally{loadingScopes.value=false}
}
async function open(){
 if(!await loadScopes())return
 editing.value=null;error.value='';secret.value=''
 form.value={name:'',expires_in_days:30,scopes:grantableScopes.value.filter(scope=>scope.endsWith(':read')&&scope!=='arthas:read'&&scope!=='resources:read'),applications:[],environments:environments.value.filter(e=>!e.protected).slice(0,2).map(e=>e.name)}
 dialog.value=true
}
async function edit(token){
 if(!await loadScopes())return
 editing.value=JSON.parse(JSON.stringify(token));error.value='';secret.value=''
 form.value={name:token.name,expires_in_days:0,scopes:[...token.scopes],applications:[...token.applications],environments:[...token.environments]}
 dialog.value=true
}
async function saveEdit(){
 if(creating.value)return
 if(await validateFields(formRef.value,form.value,{},_validationErrors))return
 if(!form.value.scopes.length){error.value='至少选择一项权限';return}
 if(!await confirmAction('将修改此 Key 的访问范围，原有待确认操作会作废。确认保存「'+form.value.name+'」？','编辑访问令牌',{confirmButtonText:'保存修改'}))return
 if(creating.value||!editing.value)return
 creating.value=true;error.value=''
 try{await api('tokens/'+encodeURIComponent(editing.value.id),{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...form.value,revision:editing.value.revision??0})});dialog.value=false;await load();toast('访问令牌已更新，Key 保持不变；客户端需重新连接以刷新工具列表。')}
 catch(e){error.value=e.message+'；原输入已保留。请核对令牌列表中的当前范围，勿直接重复提交。'}finally{creating.value=false}
}
async function removeToken(token){
 if(revoking.value)return
 revoking.value=token.id
 try{if(!await confirmAction('删除后此 Key 立即失效，并从令牌列表移除；已有调用审计保留。确认删除「'+token.name+'」？','删除访问令牌',{confirmButtonText:'确认删除'}))return
 await api('tokens/'+encodeURIComponent(token.id)+'/record',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({revision:token.revision??0})});await load()
 }catch(e){toast(e.message,'error')}finally{revoking.value=''}
}
async function create(){if(editing.value)return saveEdit();if(creating.value||secret.value)return;if(await validateFields(formRef.value,form.value,{},_validationErrors))return;if(creating.value||secret.value)return;if(!form.value.scopes.length){error.value='至少选择一项权限';return}creating.value=true;error.value='';try{const result=await api('tokens',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(form.value)});if(typeof result.secret!=='string'||!result.secret.startsWith('lp_dev_')||result.secret.length<20)throw Error('服务器未返回完整令牌，请先核对令牌列表');secret.value=result.secret;await load()}catch(e){error.value=e.message+'；结果不确定时请先刷新令牌列表核对，不要重复创建。'}finally{creating.value=false}}
function close(){if(creating.value)return;dialog.value=false;secret.value=''}
const revoking=ref('')
async function revoke(token){
 if(revoking.value)return
 revoking.value=token.id
 try{
  if(!await confirmAction('撤销后，此令牌配置的 MCP 客户端将立即无法访问。确认撤销「'+token.name+'」？','撤销访问令牌',{confirmButtonText:'确认撤销'}))return
  await api('tokens/'+encodeURIComponent(token.id),{method:'DELETE'})
  await load()
 }catch(e){toast(e.message,'error')}finally{revoking.value=''}
}
onMounted(async()=>{load();const [envs,apps]=await Promise.all([fetch('/api/resources/environments').then(r=>r.ok?r.json():[]).catch(()=>[]),fetch('/api/registry/services').then(r=>r.ok?r.json():[]).catch(()=>[])]);environments.value=Array.isArray(envs)?envs:[];applications.value=Array.isArray(apps)?apps:[]})

import OptionPicker from '../shared/components/OptionPicker.vue'

import {reactive as _validationReactive} from 'vue'
import {validateFields,setFieldErrors,scrollToValidationField} from '../shared/formValidation.js'
const _validationErrors=_validationReactive({})

import {confirmAction} from '../shared/shadcnFeedback.js'


import {Alert,AlertDescription,AlertTitle,Badge,Button,Card,CardAction,CardContent,CardFooter,CardHeader,CardTitle,Checkbox,CheckboxGroupRoot,Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle,Empty,EmptyContent,EmptyDescription,EmptyHeader,Field,FieldDescription,FieldError,FieldLabel,Input,NumberField,NumberFieldContent,NumberFieldDecrement,NumberFieldIncrement,NumberFieldInput,Spinner,Table,TableBody,TableCell,TableHead,TableHeader,TableRow,Tabs,TabsContent,TabsList,TabsTrigger} from '../shared/shadcn-ui.js'
</script>
<template><main class="mcp-page"><PageSurface><PageHeader title="MCP 访问管理" help="令牌绑定创建人的账号，按权限、应用和环境隔离。写权限默认关闭；密钥仅创建时展示一次。工作项与版本跨应用，需显式授权应用 *。"><template #actions><Button @click="open" :disabled="loadingScopes" variant="default" size="default" type="button"><Spinner v-if="loadingScopes"/>创建访问令牌</Button></template></PageHeader><Tabs :model-value="tab" @update:model-value="tab=$event;"><div class="mb-5 flex min-w-0 items-center gap-2 border-b"><TabsList variant="line" class="h-auto! min-h-9 max-w-full flex-wrap justify-start gap-x-3 gap-y-1 [&>[data-slot=tabs-trigger]]:h-9 [&>[data-slot=tabs-trigger]]:flex-none"><TabsTrigger :value="&quot;tokens&quot;">访问令牌</TabsTrigger><TabsTrigger :value="&quot;tools&quot;">工具清单</TabsTrigger><TabsTrigger :value="&quot;setup&quot;">客户端接入</TabsTrigger><TabsTrigger :value="&quot;audit&quot;">调用审计</TabsTrigger></TabsList></div><TabsContent :value="&quot;tokens&quot;" force-mount v-show="!(tab!==&quot;tokens&quot;)" class="min-w-0"><div class="console-table min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:820}).y?({x:820}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:1150}).x||({x:1150}).minWidth||1150)+'px'}"><TableHeader class="bg-muted/50"><TableRow><TableHead :style="{width:(220)+'px'}">名称</TableHead><TableHead class="w-40">关联用户</TableHead><TableHead>权限</TableHead><TableHead :style="{width:(180)+'px'}">范围</TableHead><TableHead :style="{width:(200)+'px'}">状态</TableHead><TableHead :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-muted':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-muted':''" :style="{width:(220)+'px'}">操作</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (tokens||[])" :key="typeof (&quot;id&quot;)==='function'?(&quot;id&quot;)(record):record[&quot;id&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]"><b>{{record.name}}</b><small>{{record.prefix}}…</small></template></div></TableCell><TableCell class="align-top whitespace-normal"><span>{{record.owner_name||record.owner||'未绑定'}}</span><small v-if="record.owner_name&&record.owner_name!==record.owner">{{record.owner}}</small></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]"><div class="flex flex-wrap items-center gap-2"><Badge v-for="scope in record.scopes" :key="scope" variant="secondary">{{scope}}</Badge></div></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]"><small>应用：{{record.applications?.join('、')}}</small><small>环境：{{record.environments?.join('、')}}</small></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]"><Badge :variant="(state(record)==='有效'?'green':'gray')==='red'?'destructive':'secondary'">{{state(record)}}</Badge><small>有效至：{{fmt(record.expires_at)}}</small><small>最近使用：{{fmt(record.last_used_at)}}</small></template></div></TableCell><TableCell class="align-top" :class="(pinTableActions?'right':undefined)==='right'?'sticky right-0 z-10 bg-background':(pinTableActions?'right':undefined)==='left'?'sticky left-0 z-10 bg-background':''"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record} in [{record,rowIndex}]"><div class="flex flex-wrap gap-1"><Button @click="edit(record)" variant="outline" size="sm" :disabled="!!revoking||creating||state(record)!=='有效'">编辑</Button><Button @click="revoke(record)" class="text-destructive" :variant="'ghost'" size="sm" type="button" :disabled="!!revoking||((record.revoked))">撤销</Button><Button @click="removeToken(record)" variant="ghost" size="sm" class="text-destructive" :disabled="!!revoking||creating">删除</Button></div></template></div></TableCell></TableRow></template><TableRow v-if="!(tokens||[]).length"><TableCell :colspan="6"><Empty><EmptyHeader><EmptyDescription>{{"还没有 MCP 访问令牌"}}</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></TabsContent><TabsContent :value="&quot;tools&quot;" force-mount v-show="!(tab!==&quot;tools&quot;)" class="min-w-0"><p class="mcp-hint">查询直接读取平台；写操作先预览，经明确同意后确认执行。添加变更只存草稿，构建不自动发布。</p><div class="console-table min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:720}).y?({x:720}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:720}).x||({x:720}).minWidth||720)+'px'}"><TableHeader class="bg-muted/50"><TableRow><TableHead :style="{width:(240)+'px'}">工具</TableHead><TableHead :style="{width:(200)+'px'}">名称</TableHead><TableHead :style="{width:(100)+'px'}">类型</TableHead><TableHead :style="{width:(180)+'px'}">权限</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (tools||[])" :key="typeof (&quot;name&quot;)==='function'?(&quot;name&quot;)(record):record[&quot;name&quot;]??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}">{{record["title"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}">{{record["name"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]">{{record.read_only?'查询':'操作预览 / 确认'}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]">{{record.scope||(record.read_only?'有效 MCP 令牌':'按冻结操作校验权限')}}</template></div></TableCell></TableRow></template><TableRow v-if="!(tools||[]).length"><TableCell :colspan="4"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></TabsContent><TabsContent :value="&quot;setup&quot;" force-mount v-show="!(tab!==&quot;setup&quot;)" class="min-w-0"><h3>Codex Streamable HTTP</h3><p class="mcp-hint">将以下配置加入项目的 .codex/config.toml，启动客户端前设置令牌环境变量。</p><div class="space-y-2"><pre>{{config}}</pre><Button variant="outline" size="sm" @click="copyText(config)">复制</Button></div><pre>export LOGPLATFORM_MCP_TOKEN="创建时显示的 lp_dev_…"
codex mcp list</pre><p class="mcp-hint">在 Codex 中输入 /mcp 检查连接。不要把日志、Bug 描述或 SQL 中的文字当作授权指令。</p><WorkflowSkills v-if="tab==='setup'"/></TabsContent><TabsContent :value="&quot;audit&quot;" force-mount v-show="!(tab!==&quot;audit&quot;)" class="min-w-0"><p class="mcp-hint">最近 100 条本人可见的调用记录。</p><div class="console-table min-w-0 max-w-full"><div v-if="loading" class="flex items-center gap-2 py-2" role="status"><Spinner/>正在读取</div><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:920}).y?({x:920}).y+'px':undefined}"><Table class="table-fixed min-w-[var(--table-min-width)]" :style="{'--table-min-width':(({x:920}).x||({x:920}).minWidth||920)+'px'}"><TableHeader class="bg-muted/50"><TableRow><TableHead :style="{width:(180)+'px'}">时间</TableHead><TableHead :style="{width:(180)+'px'}">令牌</TableHead><TableHead :style="{width:(200)+'px'}">工具</TableHead><TableHead :style="{width:(180)+'px'}">范围</TableHead><TableHead :style="{width:(180)+'px'}">结果</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (audit||[])" :key="typeof ('id')==='function'?('id')(record):record['id']??rowIndex"><TableRow><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]">{{fmt(record.created_at)}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}">{{record["token_name"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}">{{record["tool"]}}</div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]">{{record.service||'—'}} / {{record.environment||'—'}}</template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(true)}"><template v-for="{record} in [{record,rowIndex}]"><Badge :variant="(record.success?'green':'red')==='red'?'destructive':'secondary'">{{record.success?'成功':'失败'}}</Badge> {{record.duration_ms}} ms</template></div></TableCell></TableRow></template><TableRow v-if="!(audit||[]).length"><TableCell :colspan="5"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></TabsContent></Tabs><Dialog :open="dialog" @update:open="async v=>{if(!v){close()}}"><DialogContent class="flex max-h-[92dvh] flex-col gap-0 overflow-hidden p-0 sm:max-w-[var(--editor-width)]" :class="false?'inset-0 h-dvh max-h-dvh w-screen max-w-none translate-x-0 translate-y-0 rounded-none sm:max-w-none':''" :style="{'--editor-width':typeof (&quot;min(640px,92vw)&quot;)==='number'?(&quot;min(640px,92vw)&quot;)+'px':(&quot;min(640px,92vw)&quot;)}" :show-close-button="!creating&&!secret" @interact-outside="e=>{if(creating||secret)e.preventDefault()}" @escape-key-down="e=>{if(creating||secret)e.preventDefault()}"><DialogHeader class="shrink-0 border-b p-5 pr-12"><DialogTitle>{{secret?'访问令牌已创建':editing?'编辑访问令牌':'创建访问令牌'}}</DialogTitle><DialogDescription class="sr-only">详情与操作</DialogDescription></DialogHeader><div class="min-h-0 flex-1 overflow-auto p-5"><form v-if="!secret" ref="formRef" @submit.prevent=""><fieldset   class="min-w-0 space-y-5" :disabled="creating||!!secret"><Field data-validation-field="name" :data-validation-rules="JSON.stringify([{required:true,message:'请填写名称'}])" :data-invalid="!!_validationErrors['name']" @vue:mounted="delete _validationErrors['name']"><FieldLabel>名称</FieldLabel><Input v-model="form.name" placeholder="例如：研发只读助手"/><FieldError v-if="_validationErrors['name']">{{_validationErrors['name'].message}}</FieldError></Field><Field data-validation-field="expires_in_days" :data-invalid="!!_validationErrors['expires_in_days']" @vue:mounted="delete _validationErrors['expires_in_days']"><FieldLabel>{{editing?'有效期（天，0 保留原到期时间）':'有效期（天）'}}</FieldLabel><NumberField v-model="form.expires_in_days" :min="editing?0:1" :max="365"><NumberFieldContent><NumberFieldDecrement/><NumberFieldInput/><NumberFieldIncrement/></NumberFieldContent></NumberField><FieldError v-if="_validationErrors['expires_in_days']">{{_validationErrors['expires_in_days'].message}}</FieldError></Field><Field data-validation-field="scopes" :data-invalid="!!_validationErrors['scopes']" @vue:mounted="delete _validationErrors['scopes']">
<div class="flex items-center justify-between gap-2"><FieldLabel>权限</FieldLabel><Button variant="ghost" size="sm" type="button" :disabled="creating||!selectableScopes.length" @click="toggleScopes">{{scopesSelected?'取消全选':'全选权限'}}</Button></div>
<CheckboxGroupRoot v-model="form.scopes" class="scope-groups"><section v-for="group in scopeGroups" :key="group.label" :aria-label="group.label" class="scope-group"><h4 class="mb-3 text-sm font-medium">{{group.label}}</h4><div class="grid gap-3"><FieldLabel v-for="scope in group.scopes" :key="scope" class="flex items-center gap-2 font-normal"><Checkbox :value="scope"/>{{scope}}</FieldLabel></div></section></CheckboxGroupRoot><FieldError v-if="_validationErrors['scopes']">{{_validationErrors['scopes'].message}}</FieldError></Field><Field data-validation-field="applications" :data-validation-rules="JSON.stringify([{required:true,message:'请选择应用范围'}])" :data-invalid="!!_validationErrors['applications']" @vue:mounted="delete _validationErrors['applications']"><FieldLabel>允许的应用</FieldLabel><OptionPicker v-model="form.applications" multiple placeholder="选择或输入应用标识" class="min-w-36" :options="[{value:'*',label:'所有应用（*）'},...applications.map(a=>({value:a.name,label:a.name}))]" allow-create/><FieldError v-if="_validationErrors['applications']">{{_validationErrors['applications'].message}}</FieldError></Field><Field data-validation-field="environments" :data-validation-rules="JSON.stringify([{required:true,message:'请选择环境范围'}])" :data-invalid="!!_validationErrors['environments']" @vue:mounted="delete _validationErrors['environments']"><FieldLabel>允许的环境</FieldLabel><OptionPicker v-model="form.environments" multiple class="min-w-36" :options="environments.map(e=>({value:e.name,label:e.display_name||e.name}))" allow-create/><FieldError v-if="_validationErrors['environments']">{{_validationErrors['environments'].message}}</FieldError></Field></fieldset></form><CreatedTokenSecret v-if="secret" :secret="secret" :name="form.name"/><Alert v-if="error&&!secret" @close="error=''"><AlertDescription>{{error}}</AlertDescription></Alert></div><DialogFooter class="shrink-0 flex-wrap border-t p-4"><Button @click="close" variant="outline" size="default" type="button" :disabled="(creating)">{{secret?'我已保存，关闭':'取消'}}</Button><Button v-if="!secret" @click="create" variant="default" size="default" type="button" :disabled="(creating)"><Spinner v-if="creating"/>{{editing?'保存修改':'创建'}}</Button></DialogFooter></DialogContent></Dialog></PageSurface></main></template>
<style scoped>.mcp-page{height:100dvh;width:100%;min-width:0;overflow:auto}.mcp-page>header{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.mcp-hint{font-size:.875rem;color:var(--muted-foreground);line-height:1.7;margin:8px 0 16px}.mcp-page small{display:block;font-size:.75rem;color:var(--muted-foreground);margin-top:4px}.mcp-page pre{font:.75rem/1.7 var(--mono);white-space:pre-wrap;overflow-wrap:anywhere;background:var(--panel2);padding:12px;border-radius:var(--radius)}</style>

<style scoped></style>

<style scoped>.scope-groups{display:grid;grid-template-columns:1fr 1fr;gap:16px}.scope-group{min-width:0;padding:16px;background:var(--muted);border-radius:var(--radius)}.scope-group:first-child{grid-row:span 2}</style>
